import { ok, fail } from './result.js';
import { balanceDue } from './payments.js';
import { lineTotal, lineDiscount, lineVAT } from './invoices.js';
import { isValidDate, daysBetween } from './dates.js';
import { roundCents } from './money.js';

/**
 * Generate an overdue invoices report.
 * @param {Array<{ customerId: string, number: string, dueDate: string, status: string, lines: Array, payments?: Array }>} invoices - All invoices
 * @param {string} asOf - Cutoff date in YYYY-MM-DD format
 * @returns {{ ok: true, value: Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }> } | { ok: false, error: string }}
 */
export function overdueInvoices(invoices, asOf) {
  // Validate asOf date
  if (!isValidDate(asOf)) return fail('DATE_INVALID');

  // Filter invoices with status 'issued' or 'partially_paid' and dueDate before asOf
  const overdue = invoices
    .filter((inv) => (inv.status === 'issued' || inv.status === 'partially_paid'))
    .filter((inv) => inv.dueDate < asOf)
    .map((inv) => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  return ok(overdue);
}

/**
 * Generate a VAT summary for issued, partially paid, and paid invoices.
 * @param {Array<{ status: string, lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }> }>} invoices - All invoices
 * @returns {{ ok: true, value: Array<{ rate: number, base: number, vat: number }> }}
 */
export function vatSummary(invoices) {
  // Group by VAT rate
  const byRate = {};

  invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid' || inv.status === 'paid')
    .forEach((inv) => {
      inv.lines.forEach((line) => {
        const rate = line.vatRate;
        const base = lineTotal(line) - lineDiscount(line);
        const vat = lineVAT(line);

        if (!byRate[rate]) {
          byRate[rate] = { base: 0, vat: 0 };
        }
        byRate[rate].base += base;
        byRate[rate].vat += vat;
      });
    });

  // Convert to array and sort by rate descending
  const summary = Object.entries(byRate)
    .map(([rate, { base, vat }]) => ({
      rate: Number(rate),
      base,
      vat,
    }))
    .sort((a, b) => b.rate - a.rate);

  return ok(summary);
}

/**
 * Calculate late fee on an invoice: 0.04% per day of the amount due.
 * @param {{ dueDate: string, lines: Array, payments?: Array<{ amount: number }>, status?: string }} invoice - Invoice to check
 * @param {string} asOf - Cutoff date in YYYY-MM-DD format
 * @returns {number} Late fee amount in cents (0 if not overdue)
 */
export function lateFee(invoice, asOf) {
  // Check if invoice is overdue
  if (invoice.dueDate >= asOf) return 0;

  // Calculate days overdue
  const daysOverdue = daysBetween(invoice.dueDate, asOf);

  // Get amount due
  const amountDue = balanceDue(invoice);

  // Calculate late fee: 0.04% per day (0.0004 as decimal)
  const feeAmount = amountDue * daysOverdue * 0.0004;

  return roundCents(feeAmount);
}

